const TZ = 'Asia/Ho_Chi_Minh';
// The NocoDB node nests a row as { id, id_fields, fields }.
const rowsOf = (name) => $(name).all()
  .map((i) => i.json || {})
  .filter((j) => j.id !== undefined && j.id !== null)
  .map((j) => ({ Id: j.id, ...(j.fields || {}) }));
const settingsOf = (name) => Object.fromEntries(
  rowsOf(name).filter((r) => r.key).map((r) => [r.key, (r.value ?? '').toString().trim()]));
const parseDt = (s) => DateTime.fromISO(String(s || '').trim().replace(' ', 'T'), { setZone: true }).setZone(TZ);
const parseDate = (s) => DateTime.fromISO(String(s || '').trim().slice(0, 10), { zone: TZ });
// settings.post_window, e.g. "07:00-22:00": the times posts may go out.
const windowOf = (v) => {
  const m = String(v || '').match(/(\d{1,2}):(\d{2})\s*-\s*(\d{1,2}):(\d{2})/);
  return m ? { from: `${m[1].padStart(2, '0')}:${m[2]}`, to: `${m[3].padStart(2, '0')}:${m[4]}` } : { from: '07:00', to: '22:00' };
};
const validTime = (t) => /^([01]\d|2[0-3]):[0-5]\d$/.test(t);
const slotOf = (dt) => { const h = Math.floor(dt.hour / 3) * 3; return `${String(h).padStart(2, '0')}-${String(h + 3).padStart(2, '0')}h`; };
const TASKS = {"chat": null, "event": null, "shift": "Daily shift. Work through this list with your tools. Your final answer is your work log entry: 2 to 4 lines on what you did and why. It is not sent to your manager.\n1. If there are no active goals or no brand docs, send your manager one short message asking for what is missing, and stop.\n2. Offers: from the 15th, next month must have two offers proposed or approved; propose what is missing. For an offer that ended without a result, ask your manager how it sold (once; check your work log).\n3. Calendar: every day from tomorrow through the reminder of the last approved offer (at most 30 days ahead) has a post. Plan the free days.\n4. Material: posts in the next 7 days that need a real detail you do not have: ask your manager, all in one message.\n5. Drafts: posts publishing within the next 3 days that are still planned: write and submit each one.\n6. Drafts waiting for approval for more than a day, and posts in the next 2 days that want a picture and have none yet: one short reminder listing them.", "review": "Weekly review: your 1:1 with your manager.\n1. Call performance for 7 days and for 30 days. Read every signal: approvals, rejections, change requests, what your manager said, failed checks, metrics, audience comments, offer results.\n2. Judge each hypothesis you tested: confirmed, refuted, or not enough data yet.\n3. Look at timing and format too: which time slots, weekdays and formats (text or picture) did better for which kinds of post, and with how many posts behind each number.\n4. Update your playbook with update_playbook: add a lesson only with evidence (at least two data points, or your manager's words); revise a lesson when new data sharpens it; retire a lesson the data contradicts. Confidence follows the amount of evidence. Merge lessons that overlap. Never touch your manager's directives.\n5. Choose one or two things to test next week (a hook, an angle, a time slot) and set them on the planned posts with update_post.\n6. Your final answer is the report sent to your manager: progress on each goal, what worked, what did not, what you changed in your playbook and why, what you will test next, and what you need from them. At most 15 lines, plain text."};

const now = DateTime.now().setZone(TZ);
let input = {};
let mode = 'shift';
if ($('When called').isExecuted) {
  input = $('When called').first().json || {};
  mode = ['chat', 'event', 'shift', 'review'].includes(input.mode) ? input.mode : 'chat';
} else if ($('Weekly review').isExecuted) {
  mode = 'review';
}
let task = TASKS[mode];
if (mode === 'chat') task = `${input.text}\n\nHandle it with your tools, then answer. Your final answer is sent to your manager as your reply.`;
if (mode === 'event') task = `Something happened: ${input.text}\n\nDo the work that follows from it with your tools. Your final answer is your work log entry (1 to 3 lines), not sent to your manager.`;
return [{
  json: {
    mode,
    task,
    reply_to: input.reply_to || '',
    started_at: now.toISO(),
    session_key: mode === 'chat' ? `lark-${input.open_id || 'unknown'}` : `${mode}-${now.toFormat('yyyy-MM-dd-HHmmss')}`,
  },
}];

